Here is a complete, dependency-free Pomodoro timer in a single HTML file. Save it as `index.html` and open it in any browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Pomodoro Timer</title>
  <style>
    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 1rem;
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      background: #f5f0eb;
      transition: background-color 0.5s ease;
    }

    body.body-work {
      background-color: #fdecea;
    }

    body.body-break {
      background-color: #e8f5e9;
    }

    body.flash-work {
      animation: flash-work 0.5s ease 3;
    }

    body.flash-break {
      animation: flash-break 0.5s ease 3;
    }

    @keyframes flash-work {
      0%, 100% { background-color: #fdecea; }
      50% { background-color: #ffd54f; }
    }

    @keyframes flash-break {
      0%, 100% { background-color: #e8f5e9; }
      50% { background-color: #81c784; }
    }

    .container {
      background: rgba(255, 255, 255, 0.75);
      backdrop-filter: blur(8px);
      width: 100%;
      max-width: 420px;
      padding: 2rem;
      border-radius: 24px;
      box-shadow: 0 12px 32px rgba(0, 0, 0, 0.12);
      text-align: center;
    }

    h1 {
      margin: 0 0 1rem;
      font-size: 1.8rem;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: #333;
    }

    .settings {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      align-items: flex-end;
      gap: 0.75rem;
      margin-bottom: 1rem;
    }

    .settings label {
      display: flex;
      flex-direction: column;
      gap: 0.25rem;
      font-size: 0.8rem;
      color: #666;
    }

    .settings input {
      width: 5.5rem;
      padding: 0.5rem;
      font-size: 1rem;
      text-align: center;
      border: 1px solid #ccc;
      border-radius: 10px;
      background: #fff;
      font: inherit;
    }

    .alert {
      min-height: 2.6rem;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 0.5rem 1rem;
      border-radius: 12px;
      color: #fff;
      font-weight: 600;
      opacity: 0;
      transform: translateY(-5px);
      transition: opacity 0.3s ease, transform 0.3s ease;
    }

    .alert.show {
      opacity: 1;
      transform: translateY(0);
    }

    .alert.work {
      background-color: #d9534f;
    }

    .alert.break {
      background-color: #28a745;
    }

    .timer {
      position: relative;
      width: min(70vw, 280px);
      aspect-ratio: 1;
      margin: 1.5rem auto 0.5rem;
    }

    .timer svg {
      display: block;
      width: 100%;
      height: 100%;
    }

    .ring-back {
      fill: none;
      stroke: #e5ddd6;
      stroke-width: 10;
    }

    .ring-progress {
      fill: none;
      stroke: var(--ring-color, #d9534f);
      stroke-width: 10;
      stroke-linecap: round;
      transform: rotate(-90deg);
      transform-origin: 100px 100px;
      transition: stroke-dashoffset 0.3s linear, stroke 0.3s ease;
    }

    .body-work .ring-progress {
      --ring-color: #d9534f;
    }

    .body-break .ring-progress {
      --ring-color: #28a745;
    }

    .timer-content {
      position: absolute;
      inset: 0;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 0.2rem;
    }

    .mode-label {
      font-size: 1.25rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.15em;
      color: #666;
    }

    .time {
      font-size: 3.2rem;
      font-weight: 700;
      font-variant-numeric: tabular-nums;
      color: #222;
      line-height: 1.1;
    }

    .controls {
      display: flex;
      justify-content: center;
      gap: 0.75rem;
      margin-top: 1.5rem;
    }

    button {
      border: none;
      border-radius: 999px;
      padding: 0.75rem 1.5rem;
      font-family: inherit;
      font-size: 1rem;
      font-weight: 600;
      color: #fff;
      background: #343a40;
      cursor: pointer;
      transition: filter 0.2s, transform 0.1s;
    }

    button:hover {
      filter: brightness(1.15);
    }

    button:active {
      transform: scale(0.96);
    }

    #startPauseButton {
      background: #d9534f;
    }

    .body-break #startPauseButton {
      background: #28a745;
    }

    #applyButton {
      background: #6c757d;
      padding: 0.55rem 1rem;
      font-size: 0.9rem;
    }

    #resetButton {
      background: #6c757d;
    }

    .hint {
      font-size: 0.75rem;
      color: #888;
      margin-top: 1rem;
    }
  </style>
</head>
<body class="body-work">
  <div class="container">
    <h1>Pomodoro</h1>

    <div class="settings">
      <label>
        Work
        <input type="number" id="workInput" min="1" max="180" step="1" value="25">
      </label>
      <label>
        Break
        <input type="number" id="breakInput" min="1" max="60" step="1" value="5">
      </label>
      <button type="button" id="applyButton">Apply</button>
    </div>

    <div class="alert" id="alert" role="status" aria-live="polite"></div>

    <div class="timer">
      <svg viewBox="0 0 200 200" aria-hidden="true">
        <circle class="ring-back" cx="100" cy="100" r="88"></circle>
        <circle class="ring-progress" id="progressRing" cx="100" cy="100" r="88"></circle>
      </svg>
      <div class="timer-content">
        <span class="mode-label" id="modeLabel">Work</span>
        <span class="time" id="timeDisplay">25:00</span>
      </div>
    </div>

    <div class="controls">
      <button type="button" id="startPauseButton">Start</button>
      <button type="button" id="resetButton">Reset</button>
    </div>

    <p class="hint">Apply resets the timer with the new intervals.</p>
  </div>

  <script>
    'use strict';

    const workInput = document.getElementById('workInput');
    const breakInput = document.getElementById('breakInput');
    const applyButton = document.getElementById('applyButton');
    const startPauseButton = document.getElementById('startPauseButton');
    const resetButton = document.getElementById('resetButton');
    const modeLabel = document.getElementById('modeLabel');
    const timeDisplay = document.getElementById('timeDisplay');
    const progressRing = document.getElementById('progressRing');
    const alertEl = document.getElementById('alert');

    const radius = progressRing.r.baseVal.value;
    const circumference = 2 * Math.PI * radius;
    progressRing.style.strokeDasharray = `${circumference} ${circumference}`;

    let workSeconds = 25 * 60;
    let breakSeconds = 5 * 60;
    let totalSeconds = workSeconds;
    let timeLeft = workSeconds;
    let mode = 'work';
    let running = false;
    let timerId = null;
    let endTime = null;
    let alertTimeout = null;

    function formatTime(seconds) {
      const m = Math.floor(seconds / 60);
      const s = seconds % 60;
      return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
    }

    function updateDisplay() {
      timeDisplay.textContent = formatTime(timeLeft);

      const progress = totalSeconds > 0 ? timeLeft / totalSeconds : 0;
      progressRing.style.strokeDashoffset = circumference * (1 - progress);

      modeLabel.textContent = mode === 'work' ? 'Work' : 'Break';
      document.title = `${formatTime(timeLeft)} – ${modeLabel.textContent} | Pomodoro`;
    }

    function switchMode(newMode) {
      mode = newMode;

      if (mode === 'work') {
        totalSeconds = workSeconds;
        document.body.className = 'body-work';
      } else {
        totalSeconds = breakSeconds;
        document.body.className = 'body-break';
      }

      timeLeft = totalSeconds;
      updateDisplay();
    }

    function readMinutes(input, fallback, min, max) {
      const parsed = parseInt(input.value, 10);
      if (Number.isNaN(parsed)) return fallback;
      return Math.min(max, Math.max(min, parsed));
    }

    function clearAlert() {
      clearTimeout(alertTimeout);
      alertTimeout = null;
      alertEl.className = 'alert';
      document.body.classList.remove('flash-work', 'flash-break');
    }

    function showAlert(message, type) {
      clearTimeout(alertTimeout);

      alertEl.textContent = message;
      alertEl.className = `alert show ${type}`;

      document.body.classList.remove('flash-work', 'flash-break');
      void alertEl.offsetWidth; // restart CSS animation
      document.body.classList.add(`flash-${type}`);

      document.title = `⏰ ${message}`;

      alertTimeout = setTimeout(() => {
        alertEl.className = 'alert';
        document.body.classList.remove('flash-work', 'flash-break');
        updateDisplay();
      }, 5000);
    }

    function startTimer() {
      if (running) return;

      clearAlert();

      running = true;
      endTime = Date.now() + timeLeft * 1000;
      timerId = setInterval(tick, 250);
      startPauseButton.textContent = 'Pause';
      updateDisplay();
    }

    function pauseTimer() {
      if (!running) return;

      clearInterval(timerId);
      timerId = null;

      if (endTime) {
        timeLeft = Math.max(0, Math.ceil((endTime - Date.now()) / 1000));
      }

      endTime = null;
      running = false;
      startPauseButton.textContent = 'Resume';
      updateDisplay();
    }

    function tick() {
      if (endTime) {
        timeLeft = Math.max(0, Math.ceil((endTime - Date.now()) / 1000));
      }

      updateDisplay();

      if (timeLeft <= 0) {
        clearInterval(timerId);
        timerId = null;
        endTime = null;
        running = false;
        completePhase();
      }
    }

    function completePhase() {
      const finishedMode = mode;

      if (finishedMode === 'work') {
        switchMode('break');
        showAlert('Work session complete! Time for a break.', 'break');
        startPauseButton.textContent = 'Start Break';
      } else {
        switchMode('work');
        showAlert('Break complete! Ready for another work session?', 'work');
        startPauseButton.textContent = 'Start Work';
      }
    }

    function resetTimer() {
      clearInterval(timerId);
      timerId = null;
      endTime = null;
      running = false;

      clearAlert();
      switchMode('work');
      startPauseButton.textContent = 'Start';
    }

    function applySettings() {
      const workMin = readMinutes(workInput, 25, 1, 180);
      const breakMin = readMinutes(breakInput, 5, 1, 60);

      workSeconds = workMin * 60;
      breakSeconds = breakMin * 60;

      workInput.value = workMin;
      breakInput.value = breakMin;

      resetTimer();
    }

    startPauseButton.addEventListener('click', () => {
      if (running) {
        pauseTimer();
      } else {
        startTimer();
      }
    });

    resetButton.addEventListener('click', resetTimer);
    applyButton.addEventListener('click', applySettings);

    [workInput, breakInput].forEach((input) => {
      input.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') {
          applySettings();
        }
      });
    });

    updateDisplay();
  </script>
</body>
</html>
