<body>
  <div class="container">
    <h1>Pomodoro Timer</h1>

    <div class="settings">
      <label>
        Work (min)
        <input type="number" id="workInput" min="1" max="180" value="25">
      </label>
      <label>
        Break (min)
        <input type="number" id="breakInput" min="1" max="180" value="5">
      </label>
    </div>

    <div class="timer-card" id="timerCard">
      <div class="mode-label" id="modeLabel">Work Session</div>
      <div class="time-display" id="timeDisplay">25:00</div>
      <div class="progress-bar"><div id="progress"></div></div>
    </div>

    <div class="controls">
      <button id="startPauseBtn">Start</button>
      <button id="resetBtn">Reset</button>
    </div>

    <div class="status" id="status"></div>
  </div>

  <script>
    (() => {
      // DOM elements
      const workInput = document.getElementById('workInput');
      const breakInput = document.getElementById('breakInput');
      const modeLabel = document.getElementById('modeLabel');
      const timeDisplay = document.getElementById('timeDisplay');
      const progress = document.getElementById('progress');
      const startPauseBtn = document.getElementById('startPauseBtn');
      const resetBtn = document.getElementById('resetBtn');
      const status = document.getElementById('status');
      const timerCard = document.getElementById('timerCard');

      // Constants
      const DEFAULT_WORK = 25;
      const DEFAULT_BREAK = 5;
      const MIN = 1;
      const MAX = 180;

      // State
      let mode = 'work';          // 'work' or 'break'
      let workDuration = DEFAULT_WORK * 60;   // seconds
      let breakDuration = DEFAULT_BREAK * 60; // seconds
      let remaining = workDuration;
      let state = 'idle';         // 'idle', 'running', 'paused'
      let timerId = null;
      let alertTimeoutId = null;

      // Helper functions
      function clamp(value, min, max) {
        return Math.min(max, Math.max(min, value));
      }

      function parseInput(input, fallback) {
        const val = parseInt(input.value, 10);
        if (isNaN(val)) return fallback;
        return clamp(val, MIN, MAX);
      }

      function currentDuration() {
        return mode === 'work' ? workDuration : breakDuration;
      }

      function formatTime(seconds) {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
      }

      function updateDisplay() {
        timeDisplay.textContent = formatTime(remaining);
        modeLabel.textContent = mode === 'work' ? 'Work Session' : 'Break Session';
        const total = currentDuration();
        const percent = total > 0 ? ((total - remaining) / total) * 100 : 0;
        progress.style.width = percent + '%';
        document.title = `${formatTime(remaining)} - ${modeLabel.textContent}`;
      }

      function clearVisualAlert() {
        if (alertTimeoutId) {
          clearTimeout(alertTimeoutId);
          alertTimeoutId = null;
        }
        timerCard.classList.remove('alert');
        status.textContent = '';
      }

      function showVisualAlert(message) {
        clearVisualAlert();
        timerCard.classList.add('alert');
        status.textContent = message;
        document.title = `⏰ ${message}`;
        alertTimeoutId = setTimeout(() => {
          timerCard.classList.remove('alert');
          status.textContent = '';
          updateDisplay();
          alertTimeoutId = null;
        }, 5000);
      }

      function updateControls() {
        startPauseBtn.textContent =
          state === 'running' ? 'Pause' :
          state === 'paused' ? 'Resume' :
          'Start';

        const disable = state !== 'idle';
        workInput.disabled = disable;
        breakInput.disabled = disable;
      }

      function tick() {
        if (remaining > 0) {
          remaining--;
          updateDisplay();
        }

        if (remaining <= 0) {
          handleComplete();
        }
      }

      function handleComplete() {
        clearInterval(timerId);
        timerId = null;
        state = 'idle';

        const wasWork = mode === 'work';
        mode = wasWork ? 'break' : 'work';
        remaining = currentDuration();

        updateControls();
        updateDisplay();
        showVisualAlert(wasWork ? 'Time for a break!' : 'Back to work!');
      }

      function startTimer() {
        if (state === 'running') return;

        if (state === 'idle') {
          // Starting a new full session
          remaining = currentDuration();
        }

        state = 'running';
        clearVisualAlert();
        timerId = setInterval(tick, 1000);
        updateControls();
        updateDisplay();
      }

      function pauseTimer() {
        if (state !== 'running') return;

        clearInterval(timerId);
        timerId = null;
        state = 'paused';
        updateControls();
      }

      function resumeTimer() {
        if (state !== 'paused') return;

        state = 'running';
        clearVisualAlert();
        timerId = setInterval(tick, 1000);
        updateControls();
        updateDisplay();
      }

      function resetTimer() {
        clearInterval(timerId);
        timerId = null;
        state = 'idle';
        mode = 'work';
        remaining = workDuration;

        clearVisualAlert();
        updateControls();
        updateDisplay();
      }

      function handleWorkInputChange() {
        const val = parseInput(workInput, DEFAULT_WORK);
        workInput.value = val;
        workDuration = val * 60;

        if (mode === 'work') {
          remaining = workDuration;
        }
        updateDisplay();
      }

      function handleBreakInputChange() {
        const val = parseInput(breakInput, DEFAULT_BREAK);
        breakInput.value = val;
        breakDuration = val * 60;

        if (mode === 'break') {
          remaining = breakDuration;
        }
        updateDisplay();
      }

      // Event listeners
      startPauseBtn.addEventListener('click', () => {
        if (state === 'running') {
          pauseTimer();
        } else if (state === 'paused') {
          resumeTimer();
        } else {
          startTimer();
        }
      });

      resetBtn.addEventListener('click', resetTimer);

      workInput.addEventListener('change', handleWorkInputChange);
      breakInput.addEventListener('change', handleBreakInputChange);

      // Initialize
      updateControls();
      updateDisplay();
    })();
  </script>
</body>
</html>
```

**How it works:**

- **Configurable intervals:** Adjust the work and break durations using the number inputs. Changes are applied when the timer is idle.
- **Pause/Resume:** The main button toggles between Start, Pause, and Resume.
- **Reset:** Returns the timer to a fresh work session.
- **Visual alerts:** When a session ends, the timer card pulses red and a status message appears. The page title also changes to alert you.
- **Responsive UI:** The layout adapts to small screens.

No external libraries or dependencies are required.

The problem is that the `debounce` function never clears the previously scheduled timeout before setting a new one. Each time the returned function is called, it creates a new `setTimeout` without canceling the old one. As a result, if the function is invoked multiple times within the delay period, all scheduled timeouts will eventually fire, causing `fn` to be called multiple times instead of just once after the last call.

**Corrected version:**

```javascript
function debounce(fn, delay) {
  let timeout;
  return function(...args) {
    clearTimeout(timeout);               // cancel any pending execution
    timeout = setTimeout(() => {
      fn.apply(this, args);              // preserve `this` and arguments
    }, delay);
  };
}
```

**Key changes:**
- `clearTimeout(timeout)` is called before setting a new timeout, ensuring only the most recent call is executed.
- Rest parameters (`...args`) are used to capture arguments cleanly, avoiding reliance on the `arguments` object inside the arrow function (though the original approach would also work if `arguments` were captured in a variable).
- The arrow function still correctly inherits `this` from the outer function, so `fn.apply(this, args)` preserves the intended context.

Now the function behaves as a proper debounce: it waits for a pause in calls before executing `fn` only once.

The problem is that the previous timeout is never cleared. Each call schedules a new `setTimeout`, so after enough time passes, every scheduled call fires. A debounce should cancel the pending timer on each new call and only run the function once after the input settles.

```js
function debounce(fn, delay) {
  let timeout;

  return function (...args) {
    const context = this;

    clearTimeout(timeout);

    timeout = setTimeout(() => {
      fn.apply(context, args);
    }, delay);
  };
}
```

This version safely cancels the previous timer before starting a new one, preserving the correct `this` and arguments.
